use std::path::is_separator;

use smallvec::SmallVec;

use crate::test_log;
use crate::pattern::Ast;

type Id = u16;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum TransitionRule {
    // Epsilon classes
    Epsilon(Id),
    /// Epsilon edges generated by * or **. Why? When * or ** are part of the
    /// parse, they tag the automaton as being a non-literal match, *even if
    /// the rule matched no characters*. This guarantees that the pattern '.*'
    /// never matches the virtual directory '.'.
    WildEpsilon(Id),
    // Character classes
    Char(char, Id),
    Sep(Id),
    /// Matches anything except for Sep (used by ?, *)
    Wildcard(Id),
    /// Matches anything including Sep (used by **)
    Any(Id),
}

impl TransitionRule {
    fn is_literal(&self) -> bool {
        match self {
            Self::WildEpsilon(_)
            | Self::Wildcard(_)
            | Self::Any(_) => false,
            Self::Epsilon(_)
            | Self::Sep(_)
            | Self::Char(_, _) => true,
        }
    }

    fn is_epsilon(&self) -> bool {
        matches!(self, Self::Epsilon(_) | Self::WildEpsilon(_))
    }

    fn next(&self) -> Id {
        match self {
            Self::Epsilon(target)
            | Self::WildEpsilon(target)
            | Self::Char(_, target)
            | Self::Sep(target)
            | Self::Wildcard(target)
            | Self::Any(target) => *target,
        }
    }

    fn matches(&self, token: char) -> bool {
        match self {
            Self::Char(c, _) => token == *c,
            Self::Sep(_) => is_separator(token),
            Self::Wildcard(_) => !is_separator(token),
            Self::Any(_) => true,
            // Epsilon transitions never consume input
            Self::Epsilon(_) | TransitionRule::WildEpsilon(_) => false,
        }
    }
}

type Transition = TransitionRule;

#[derive(Debug, Default)]
struct State {
    transitions: SmallVec<[Transition; 1]>,
    // True if the state has any non-epsilon transition, or is terminal
    is_epsilon_frontier: bool,
}

#[derive(Debug)]
struct StateMachine {
    states: Vec<State>,
}

impl StateMachine {
    fn new() -> Self {
        let mut states = vec![
            State::default(), // Initial
            State::default(), // Terminal
        ];
        states[1].is_epsilon_frontier = true;
        Self {
            states,
        }
    }

    fn new_state(&mut self) -> Id {
        let id = self.states.len() as Id;
        self.states.push(State::default());
        id
    }

    fn connect(&mut self, from: Id, transition: Transition) {
        let state = &mut self.states[from as usize];
        state.is_epsilon_frontier |= !transition.is_epsilon();
        state.transitions.push(transition);
    }

    #[cfg(test)]
    fn transitions(&self, from: Id, to: Id) -> Vec<Transition> {
        self.states[from as usize].transitions.iter()
            .filter(|t| t.next() == to)
            .cloned()
            .collect()
    }

    fn initial(&self) -> Id {
        0
    }

    fn terminal(&self) -> Id {
        1
    }
}

/// Compiles `ast` into `sm` as a sub-machine entering at `initial` and
/// exiting at `terminal`.
fn compile(sm: &mut StateMachine, ast: &Ast, initial: Id, terminal: Id) {
    match ast {
        Ast::Empty => sm.connect(initial, Transition::Epsilon(terminal)),
        Ast::Char(c) => sm.connect(initial, Transition::Char(*c, terminal)),
        Ast::Sep => sm.connect(initial, Transition::Sep(terminal)),
        Ast::Wildcard => sm.connect(initial, Transition::Wildcard(terminal)),
        Ast::Star => {
            sm.connect(initial, Transition::Wildcard(terminal));
            sm.connect(initial, Transition::WildEpsilon(terminal));
            sm.connect(terminal, Transition::WildEpsilon(initial));
        }
        Ast::StarStar => {
            sm.connect(initial, Transition::Any(terminal));
            sm.connect(initial, Transition::WildEpsilon(terminal));
            sm.connect(terminal, Transition::WildEpsilon(initial));
        }
        Ast::Sequence(nodes) => {
            let mut initial = initial;
            for (i, node) in nodes.iter().enumerate() {
                let terminal = if i + 1 == nodes.len() {
                    terminal
                } else {
                    sm.new_state()
                };
                compile(sm, node, initial, terminal);
                initial = terminal;
            }
        }
        Ast::Alternative(branches) => {
            for branch in branches {
                compile(sm, branch, initial, terminal);
            }
        }
    }
}

fn from_pattern(ast: &Ast) -> StateMachine {
    let mut sm = StateMachine::new();
    compile(&mut sm, ast, 0, 1);
    sm
}

#[derive(Debug, Default)]
struct LiveSet {
    states: Vec<u32>,
    generation: u32,
}

impl LiveSet {
    fn new(size: usize) -> Self {
        Self {
            states: vec![0; size],
            generation: 1,
        }
    }

    fn clear(&mut self) {
        self.generation = self.generation.wrapping_add(1);
        if self.generation == 0 {
            self.states.fill(0);
            self.generation = 1;
        }
    }

    fn is_live(&self, state: Id) -> bool {
        self.states[state as usize] == self.generation
    }

    fn mark_live(&mut self, state: Id) {
        self.states[state as usize] = self.generation;
    }
}

#[derive(Debug)]
struct StringMatcher<'a> {
    machine: &'a StateMachine,
    input: &'a str,
    states: Vec<Id>,
    new_states: Vec<Id>, // Reuse memory
    live: LiveSet,
}

impl<'a> StringMatcher<'a> {
    fn new(machine: &'a StateMachine, input: &'a str) -> Self {
        Self {
            machine,
            input,
            states: vec![0],
            new_states: Vec::new(),
            live: LiveSet::new(machine.states.len()),
        }
    }

    // Follows epsilon transitions until all states are on the frontier.
    fn expand_epsilon(&mut self) {
        self.live.clear();
        let live = &mut self.live;
        let machine = self.machine;

        let mut push_state = |queue: &mut Vec<Id>, s: Id| {
            if !live.is_live(s) {
                live.mark_live(s);
                queue.push(s);
            }
        };

        let queue = &mut self.new_states;
        self.states.iter().for_each(|&s| push_state(queue, s));
        self.states.clear();
        while let Some(s) = queue.pop() {
            if machine.states[s as usize].is_epsilon_frontier {
                self.states.push(s);
            }
            for t in &machine.states[s as usize].transitions {
                if let TransitionRule::Epsilon(next) | TransitionRule::WildEpsilon(next) = t {
                    push_state(queue, *next);
                }
            }
        }
    }

    fn expand_matching(&mut self, c: char) {
        self.live.clear();
        for &s in &self.states {
            for t in &self.machine.states[s as usize].transitions {
                let next = t.next();
                if t.is_epsilon() || self.live.is_live(next) {
                    test_log!("{c},{s},{t:?}... skipped");
                    continue;
                }
                if t.matches(c) {
                    test_log!("{c},{s},{t:?}... matched");
                    self.new_states.push(next);
                    self.live.mark_live(next);
                } else {
                    test_log!("{c},{s},{t:?}... failed");
                }
            }
        }
        std::mem::swap(&mut self.states, &mut self.new_states);
        self.new_states.clear();
    }

    fn step(&mut self, c: char) {
        self.expand_epsilon();
        test_log!("ε {:?}", self.states);
        self.expand_matching(c);
        test_log!("{} {:?}", c, self.states);
    }

    // Runs until full input has been consumed, or no more live states remain.
    fn run(&mut self) -> bool {
        test_log!("{:?}", self.machine.states);
        for c in self.input.chars() {
            self.step(c);
            if self.states.is_empty() {
                return false;
            }
        }
        self.live.clear();
        self.expand_epsilon();
        self.states.contains(&self.machine.terminal())
    }
}

fn match_string(machine: &StateMachine, target: &str) -> bool {
    StringMatcher::new(machine, target).run()
}

#[cfg(test)]
mod tests {
    use super::*;

    use crate::pattern::parse_ast;

    fn machine(s: &str) -> StateMachine {
        from_pattern(&parse_ast(s).unwrap())
    }

    #[test]
    fn test_compile() {
        let sm = machine("");
        assert_eq!(sm.transitions(0, 1), vec![Transition::Epsilon(1)]);

        let sm = machine("a");
        assert_eq!(sm.transitions(0, 1), vec![Transition::Char('a', 1)]);

        let sm = machine("/");
        assert_eq!(sm.transitions(0, 1), vec![Transition::Sep(1)]);

        let sm = machine("?");
        assert_eq!(sm.transitions(0, 1), vec![Transition::Wildcard(1)]);

        let sm = machine("*");
        assert_eq!(sm.transitions(0, 1), vec![Transition::Wildcard(1), Transition::WildEpsilon(1)]);
        assert_eq!(sm.transitions(1, 0), vec![Transition::WildEpsilon(0)]);

        let sm = machine("**");
        assert_eq!(sm.transitions(0, 1), vec![Transition::Any(1), Transition::WildEpsilon(1)]);
        assert_eq!(sm.transitions(1, 0), vec![Transition::WildEpsilon(0)]);

        let sm = machine("abc");
        assert_eq!(sm.transitions(0, 2), vec![Transition::Char('a', 2)]);
        assert_eq!(sm.transitions(2, 3), vec![Transition::Char('b', 3)]);
        assert_eq!(sm.transitions(3, 1), vec![Transition::Char('c', 1)]);

        let sm = machine("{a,b}");
        assert_eq!(
            sm.transitions(0, 1),
            vec![Transition::Char('a', 1), Transition::Char('b', 1)]
        );

        let sm = machine("{ab,cd}");
        assert_eq!(sm.transitions(0, 2), vec![Transition::Char('a', 2)]);
        assert_eq!(sm.transitions(2, 1), vec![Transition::Char('b', 1)]);
        assert_eq!(sm.transitions(0, 3), vec![Transition::Char('c', 3)]);
        assert_eq!(sm.transitions(3, 1), vec![Transition::Char('d', 1)]);
        assert_eq!(sm.transitions(0, 1), vec![]);
    }

    fn matches(pattern: &str, target: &str) -> bool {
        match_string(&machine(pattern), target)
    }

    #[test]
    fn test_isolated() {
        assert!(matches("a*b", "ab"));
    }

    #[test]
    fn test_match() {
        assert!(matches("", ""));
        assert!(!matches("", "a"));
        assert!(matches("abc", "abc"));
        assert!(!matches("abc", "ab"));
        assert!(!matches("abc", "abcd"));
        assert!(matches("héllo", "héllo"));

        assert!(matches("a/b", "a/b"));
        assert!(!matches("a/b", "ab"));

        assert!(matches("?", "a"));
        assert!(matches("?", "é"));
        assert!(!matches("?", "/"));
        assert!(!matches("?", ""));
        assert!(!matches("?", "ab"));
        assert!(matches("a?c", "abc"));
        assert!(!matches("a?c", "a/c"));

        assert!(matches("*", ""));
        assert!(matches("*", "abc"));
        assert!(!matches("*", "/"));
        assert!(matches("a*b", "ab"));
        assert!(matches("a*b", "axxb"));
        assert!(!matches("a*b", "a/b"));

        assert!(matches("**", ""));
        assert!(matches("**", "a/b/c"));
        assert!(matches("a**b", "a/xb"));
        assert!(!matches("a**b", "a/b/c"));
        assert!(matches("a/**", "a/b/c"));
        assert!(!matches("a/**", "a"));
        assert!(matches("***", "a/b"));

        assert!(matches("{a,b}", "a"));
        assert!(matches("{a,b}", "b"));
        assert!(!matches("{a,b}", "c"));
        assert!(matches("{ab,cd}", "cd"));
        assert!(matches("{,a}", ""));
        assert!(matches("{a,{b,c}d}", "bd"));
        assert!(!matches("{a,{b,c}d}", "bcd"));
        assert!(matches("{a,*.rs}", "a"));
        assert!(matches("{a,*.rs}", "main.rs"));
        assert!(!matches("{a,*.rs}", "b"));

        assert!(matches(r"\*", "*"));
        assert!(!matches(r"\*", "**"));
        assert!(matches(r"\?", "?"));
        assert!(matches(r"\{a\}", "{a}"));
        assert!(matches(r"a\,b", "a,b"));
        assert!(matches(r"a\*b", "a*b"));

        assert!(matches(r"\\", "\\"));
        #[cfg(not(windows))]
        assert!(!matches(r"\\", "/"));
        #[cfg(windows)]
        assert!(matches(r"\\", "/"));

        assert!(matches("?*", "ab"));
        assert!(!matches("?*", ""));
        assert!(matches("*/*", "a/b"));
        assert!(!matches("*/*", "a/b/c"));
        assert!(matches("**/b", "x/y/b"));
        assert!(matches("{a,b}?c", "axc"));
        assert!(matches("./*", "./a"));
        assert!(matches("*/.", "a/."));
        assert!(matches("src/**/*.rs", "src/a/b.rs"));
        assert!(!matches("src/**/*.rs", "src.rs"));
    }
}
